<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#101827"><meta name="description" content="Interactive appointment booking demo powered by Laravel, PostgreSQL and Redis."><title>Appointment Booking Demo</title>
<style>
:root{color-scheme:dark;--bg:#0b1220;--panel:#111c2d;--muted:#94a3b8;--line:#26364b;--text:#edf4ff;--accent:#5eead4;--blue:#7dd3fc;--danger:#fda4af}*{box-sizing:border-box}body{margin:0;background:radial-gradient(ellipse at 15% -10%,#1b3b51 0,transparent 35%),var(--bg);color:var(--text);font:16px/1.55 Inter,ui-sans-serif,system-ui,-apple-system,"Segoe UI",sans-serif}.wrap{max-width:1100px;margin:auto;padding:36px 22px 72px}.top{display:flex;justify-content:space-between;align-items:center;gap:18px;margin-bottom:58px}.brand{font-weight:750}.brand span,.eyebrow{color:var(--accent)}.tag{font-size:12px;color:var(--accent);border:1px solid #25665e;border-radius:999px;padding:6px 11px}.hero{max-width:750px;margin-bottom:34px}.eyebrow{font-size:12px;font-weight:800;letter-spacing:.16em;text-transform:uppercase}.hero h1{font-size:clamp(36px,6vw,62px);line-height:1.04;letter-spacing:-.045em;margin:14px 0}.hero p{color:#b6c5d9;font-size:18px;max-width:690px;margin:0}.grid{display:grid;grid-template-columns:minmax(0,1.5fr) minmax(280px,.8fr);gap:18px;align-items:start}.panel{background:linear-gradient(150deg,#142238,#101a2a);border:1px solid var(--line);border-radius:20px;padding:24px;box-shadow:0 18px 60px #02061755}.panel h2{font-size:20px;margin:0 0 5px}.sub{color:var(--muted);margin:0 0 20px;font-size:14px}label{display:block;font-size:13px;font-weight:700;color:#cbd5e1;margin:14px 0 6px}select,input{width:100%;padding:12px 13px;color:var(--text);background:#0b1422;border:1px solid #35465d;border-radius:11px;font:inherit;outline:none}select:focus,input:focus{border-color:var(--accent);box-shadow:0 0 0 3px #5eead422}.row{display:grid;grid-template-columns:1fr 1fr;gap:12px}.slots{display:flex;flex-wrap:wrap;gap:8px;margin-top:12px}.slot,.tab{border:1px solid #38516a;background:#132237;color:var(--text);padding:8px 12px;border-radius:10px;cursor:pointer}.slot:hover,.slot.selected,.tab.active{border-color:var(--accent);color:var(--accent)}button.primary{border:0;background:linear-gradient(100deg,#5eead4,#7dd3fc);color:#071522;font-weight:800;border-radius:11px;padding:12px 17px;cursor:pointer;margin-top:17px}button:disabled{opacity:.5;cursor:not-allowed}.hint{font-size:12px;color:var(--muted)}.notice{display:none;margin-top:14px;border:1px solid #38516a;border-radius:12px;padding:12px;color:#dbeafe;white-space:pre-wrap}.notice.error,.notice.ok{display:block}.notice.error{border-color:#7f3448;color:var(--danger)}.notice.ok{border-color:#25665e;color:var(--accent)}.auth{border-top:1px solid var(--line);margin-top:22px;padding-top:20px}.auth-tabs{display:flex;gap:8px}.secure{background:#0b1422;border:1px solid var(--line);border-radius:14px;padding:14px;margin-top:18px;color:#bdcce0;font-size:13px}.secure strong{color:var(--text)}.foot{color:var(--muted);font-size:12px;margin-top:22px}.foot a{color:var(--blue)}@media(max-width:760px){.grid{grid-template-columns:1fr}.top{margin-bottom:38px}.wrap{padding-inline:16px}.panel{padding:20px}}
</style></head><body><main class="wrap">
<header class="top"><div class="brand">PARSA<span>.</span> API LAB</div><span class="tag">INTERACTIVE DEMO · PORTFOLIO PROJECT</span></header>
<section class="hero"><div class="eyebrow">Laravel · PostgreSQL · Redis</div><h1>Book an appointment,<br>without the guesswork.</h1><p>Explore live provider availability and create a temporary booking hold. This demo exercises the API’s scheduling, authentication and booking flow.</p></section>
<div class="grid"><section class="panel"><h2>Find a time</h2><p class="sub">Choose a provider, service and future date to load available slots from the API.</p>
<label for="provider">Provider</label><select id="provider"><option value="">Loading providers…</option></select>
<label for="service">Service</label><select id="service" disabled><option value="">Select a provider first</option></select>
<div class="row"><div><label for="date">Date</label><input id="date" type="date"></div><div><label for="timezone">Timezone</label><input id="timezone" readonly value="—"></div></div>
<button class="primary" id="load">Find available times</button><div id="slots" class="slots" aria-live="polite"></div><button class="primary" id="book" disabled>Create booking hold</button><div id="booking-message" class="notice" role="status" aria-live="polite"></div></section>
<aside class="panel"><h2>Try the booking flow</h2><p class="sub">Create a customer account or sign in. Your token stays in this tab’s memory and is cleared when you leave.</p>
<div class="auth-tabs"><button class="tab active" data-mode="login" type="button">Sign in</button><button class="tab" data-mode="register" type="button">Create account</button></div>
<form id="auth"><div id="name-wrap" hidden><label for="name">Name</label><input id="name" autocomplete="name" maxlength="120"></div><label for="email">Email</label><input id="email" type="email" autocomplete="email" required maxlength="255"><label for="password">Password</label><input id="password" type="password" autocomplete="current-password" minlength="8" required><div id="confirm-wrap" hidden><label for="confirm">Confirm password</label><input id="confirm" type="password" autocomplete="new-password" minlength="8"></div><button class="primary" id="auth-submit">Sign in</button></form>
<div id="auth-message" class="notice" role="status" aria-live="polite"></div><div class="secure"><strong>Demo safety</strong><br>Use a throwaway email and password. This is a portfolio demo, not a production booking service. No payment credentials or webhook secret are exposed in the browser.</div><p class="foot">API docs: <a href="/docs/openapi.yaml">OpenAPI specification</a> · <a href="https://github.com/parsazabihii/appointment-api">Source on GitHub</a></p></aside></div>
<p class="foot">Booking creates a pending hold only. Payment is not processed in this public interface.</p></main>
<script>
(()=>{const api='/api',el=id=>document.getElementById(id),provider=el('provider'),service=el('service'),date=el('date'),slots=el('slots'),book=el('book');let token=null,picked=null,mode='login';
const msg=(node,text,type='')=>{node.textContent=text;node.className='notice'+(type?' '+type:'')};
async function req(path,opt={}){const headers={Accept:'application/json',...(opt.headers||{})};if(opt.body)headers['Content-Type']='application/json';if(token)headers.Authorization='Bearer '+token;const r=await fetch(api+path,{...opt,headers}),data=await r.json().catch(()=>({}));if(!r.ok){const errors=data.errors?Object.values(data.errors).flat().join('\n'):'';throw Error(errors||data.message||'Request failed. Please try again.')}return data}
function option(sel,label,value){const o=document.createElement('option');o.textContent=label;o.value=value;sel.append(o)}
function clearSlots(){slots.replaceChildren();picked=null;book.disabled=true}
async function loadProviders(){try{const d=await req('/providers');provider.replaceChildren();option(provider,'Choose a provider','');(d.data||[]).forEach(x=>option(provider,x.name+(x.bio?' — '+x.bio:''),x.id));if(!d.data?.length)option(provider,'No active providers are available','')}catch(e){provider.replaceChildren();option(provider,'Could not load providers','');msg(el('booking-message'),e.message,'error')}}
provider.addEventListener('change',()=>{clearSlots();service.replaceChildren();option(service,'Choose a service','');service.disabled=true;el('timezone').value='—';if(!provider.value)return;req('/providers/'+encodeURIComponent(provider.value)).then(d=>{el('timezone').value=d.data.timezone||'—';(d.data.services||[]).forEach(x=>option(service,x.name+' · '+x.duration_minutes+' min',x.id));service.disabled=false;if(!d.data.services?.length)option(service,'No active services','')}).catch(e=>msg(el('booking-message'),e.message,'error'))});
el('load').addEventListener('click',async()=>{clearSlots();if(!provider.value||!service.value||!date.value){msg(el('booking-message'),'Choose a provider, service and date first.','error');return}const b=el('load');b.disabled=true;b.textContent='Checking availability…';try{const d=await req('/providers/'+encodeURIComponent(provider.value)+'/slots?date='+encodeURIComponent(date.value)+'&service_id='+encodeURIComponent(service.value));if(!d.data?.length){slots.textContent='No available times. Try another date.';return}d.data.forEach(x=>{const b=document.createElement('button');b.type='button';b.className='slot';b.textContent=x.local_start.slice(11)+' – '+x.local_end.slice(11)+' ('+x.timezone+')';b.onclick=()=>{slots.querySelectorAll('.slot').forEach(y=>y.classList.remove('selected'));b.classList.add('selected');picked=x;book.disabled=!token};slots.append(b)})}catch(e){msg(el('booking-message'),e.message,'error')}finally{b.disabled=false;b.textContent='Find available times'}});
function setMode(m){mode=m;document.querySelectorAll('.tab').forEach(x=>x.classList.toggle('active',x.dataset.mode===m));el('name-wrap').hidden=m!=='register';el('confirm-wrap').hidden=m!=='register';el('name').required=m==='register';el('confirm').required=m==='register';el('password').autocomplete=m==='register'?'new-password':'current-password';el('auth-submit').textContent=m==='register'?'Create customer account':'Sign in';msg(el('auth-message'),'')}
document.querySelectorAll('.tab').forEach(x=>x.onclick=()=>setMode(x.dataset.mode));
el('auth').addEventListener('submit',async e=>{e.preventDefault();token=null;book.disabled=true;const data={email:el('email').value,password:el('password').value,device_name:'portfolio-demo'};if(mode==='register')Object.assign(data,{name:el('name').value,password_confirmation:el('confirm').value,role:'customer'});const b=el('auth-submit');b.disabled=true;try{const d=await req(mode==='register'?'/auth/register':'/auth/login',{method:'POST',body:JSON.stringify(data)});token=d.token;msg(el('auth-message'),'Signed in as '+d.data.name+'. Select a time to continue.','ok');b.textContent='Signed in';el('email').disabled=el('password').disabled=el('name').disabled=el('confirm').disabled=true;book.disabled=!picked}catch(err){token=null;msg(el('auth-message'),err.message,'error');b.disabled=false}});
book.addEventListener('click',async()=>{if(!token||!picked)return;book.disabled=true;book.textContent='Creating hold…';try{const d=await req('/appointments',{method:'POST',headers:{'Idempotency-Key':crypto.randomUUID()},body:JSON.stringify({provider_id:Number(provider.value),service_id:Number(service.value),starts_at:picked.starts_at})});msg(el('booking-message'),'Booking hold created. Status: '+d.data.status+'. Expires: '+(d.data.hold_expires_at||'per API configuration')+'. Payment is not processed in this demo.','ok');clearSlots()}catch(e){msg(el('booking-message'),e.message,'error');book.disabled=false}finally{book.textContent='Create booking hold'}});
const tomorrow=new Date();tomorrow.setDate(tomorrow.getDate()+1);date.value=[tomorrow.getFullYear(),String(tomorrow.getMonth()+1).padStart(2,'0'),String(tomorrow.getDate()).padStart(2,'0')].join('-');date.min=date.value;date.onchange=clearSlots;service.onchange=clearSlots;loadProviders()})();
</script></body></html>